def _sha256_file(path):
    try:
        h = hashlib.sha256()
        with open(path, "rb") as f:
            while True:
                chunk = f.read(1024 * 1024)
                if not chunk:
                    break
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None


def _ensure_embedded_pypdf_zip():
    local_appdata = os.environ.get("LOCALAPPDATA")
    if not local_appdata:
        local_appdata = os.path.join(os.path.expanduser("~"), "AppData", "Local")

    vendor_dir = os.path.join(local_appdata, "AnTools", "Vendor")
    try:
        if not os.path.isdir(vendor_dir):
            os.makedirs(vendor_dir)
    except Exception:
        # Fallback to TEMP when LOCALAPPDATA cannot be written.
        vendor_dir = os.path.join(os.environ.get("TEMP", TOOL_DIR), "AnTools", "Vendor")
        if not os.path.isdir(vendor_dir):
            os.makedirs(vendor_dir)

    vendor_zip = os.path.join(
        vendor_dir,
        "pypdf_{}_py3.zip".format(_PYPDF_VENDOR_VERSION.replace(".", "_")),
    )

    needs_write = True
    if os.path.exists(vendor_zip):
        needs_write = _sha256_file(vendor_zip) != _PYPDF_VENDOR_SHA256

    if needs_write:
        payload = base64.b64decode(_PYPDF_VENDOR_B64)
        temp_zip = vendor_zip + ".tmp"
        with open(temp_zip, "wb") as f:
            f.write(payload)
        if _sha256_file(temp_zip) != _PYPDF_VENDOR_SHA256:
            try:
                os.remove(temp_zip)
            except Exception:
                pass
            raise Exception("Embedded pypdf payload checksum mismatch.")
        try:
            if os.path.exists(vendor_zip):
                os.remove(vendor_zip)
        except Exception:
            pass
        os.rename(temp_zip, vendor_zip)

    return vendor_zip


