def alert(message, exitscript=False, title=None, icon=None):
    if title is None:
        title = "Bluebeam PDF Review V{}".format(TOOL_VERSION)
    if icon is None:
        icon = MessageBoxIcon.Information
    try:
        MessageBox.Show(str(message), str(title), MessageBoxButtons.OK, icon)
    except Exception:
        try:
            print(str(message))
        except Exception:
            pass
    if exitscript:
        raise SystemExit


def ask_yes_no(message, title=None):
    if title is None:
        title = "Bluebeam PDF Review V{}".format(TOOL_VERSION)
    result = MessageBox.Show(
        str(message), str(title), MessageBoxButtons.YesNo, MessageBoxIcon.Question
    )
    return result == DialogResult.Yes


