def _cfg_get(name, default):
    try:
        return getattr(config, name)
    except Exception:
        return default


def _cfg_get_bool(name, default):
    value = _cfg_get(name, default)
    if isinstance(value, bool):
        return value
    text_value = str(value).strip().lower()
    if text_value in ("1", "true", "yes", "on"):
        return True
    if text_value in ("0", "false", "no", "off", ""):
        return False
    return bool(default)


def _cfg_escape(value):
    if value is None:
        return ""
    return str(value).replace("%", "%%")


def _cfg_set(name, value):
    setattr(config, name, _cfg_escape(value))


