def get_id_int(element_id):
    if element_id is None:
        return -1
    try:
        return int(element_id.Value)
    except Exception:
        try:
            return int(element_id.IntegerValue)
        except Exception:
            return -1


def to_element_id(value):
    try:
        return ElementId(int(value))
    except Exception:
        return None


def get_element_by_saved_id(document, value):
    eid = to_element_id(value)
    if eid is None:
        return None
    try:
        elem = document.GetElement(eid)
        if elem is not None and elem.IsValidObject:
            return elem
    except Exception:
        pass
    return None


def safe_filename(text):
    bad = '<>:"/\\|?*'
    result = str(text or "")
    for ch in bad:
        result = result.replace(ch, "_")
    result = result.strip().strip(".")
    return result or "PDF"


def xyz_distance(a, b):
    try:
        return a.DistanceTo(b)
    except Exception:
        dx = a.X - b.X
        dy = a.Y - b.Y
        dz = a.Z - b.Z
        return math.sqrt(dx * dx + dy * dy + dz * dz)


def normalized(vec):
    try:
        if vec.GetLength() < 1.0e-12:
            return None
        return vec.Normalize()
    except Exception:
        return None


def clamp(value, low, high):
    return max(low, min(high, value))


def get_document_key(document):
    try:
        path = document.PathName or ""
    except Exception:
        path = ""
    if path:
        try:
            return os.path.normcase(os.path.abspath(path))
        except Exception:
            return path
    try:
        return "UNSAVED::{}".format(document.Title)
    except Exception:
        return "UNSAVED"


def get_view_key(document, view):
    raw = "{}|{}".format(get_document_key(document), view.UniqueId)
    return hashlib.sha1(raw.encode("utf-8", "ignore")).hexdigest()


