def get_pdf_fingerprint(pdf_path):
    st = os.stat(pdf_path)
    try:
        mtime = int(st.st_mtime_ns)
    except Exception:
        mtime = int(st.st_mtime * 1000000000.0)
    raw = "{}|{}|{}".format(
        os.path.normcase(os.path.abspath(pdf_path)), int(st.st_size), mtime
    )
    return hashlib.sha1(raw.encode("utf-8", "ignore")).hexdigest()


def open_reader_from_stream(stream):
    reader = PdfReader(stream, strict=False)
    if getattr(reader, "is_encrypted", False):
        decrypted = 0
        try:
            decrypted = reader.decrypt("")
        except Exception:
            decrypted = 0
        if not decrypted:
            raise Exception("PDF đang được mã hóa/password và tool không mở được.")
    return reader


def get_pdf_page_count(pdf_path):
    if not pdf_path or not os.path.exists(pdf_path):
        return 0
    with open(pdf_path, "rb") as stream:
        reader = open_reader_from_stream(stream)
        return int(len(reader.pages))


def pdf_name(value, default=""):
    try:
        return str(value)
    except Exception:
        return default


def resolve_pdf_object(value):
    try:
        return value.get_object()
    except Exception:
        return value


def pdf_float(value, default=0.0):
    try:
        return float(resolve_pdf_object(value))
    except Exception:
        return float(default)


def pdf_int(value, default=0):
    try:
        return int(resolve_pdf_object(value))
    except Exception:
        return int(default)


def pdf_number_list(value):
    obj = resolve_pdf_object(value)
    if obj is None:
        return []
    result = []
    try:
        for item in obj:
            result.append(float(resolve_pdf_object(item)))
    except Exception:
        return []
    return result


def annot_subtype(annot):
    try:
        return pdf_name(annot.get("/Subtype", ""), "")
    except Exception:
        return ""


def annot_flags(annot):
    try:
        return int(annot.get("/F", 0) or 0)
    except Exception:
        return 0


def is_visual_markup_annotation(annot):
    subtype = annot_subtype(annot)
    if subtype in NON_MARKUP_SUBTYPES:
        return False
    if annot_flags(annot) & NON_VISIBLE_FLAG_MASK:
        return False
    if not subtype:
        return False
    return True


def get_annotation_text(annot, key):
    try:
        value = resolve_pdf_object(annot.get(key, ""))
        if value is None:
            return ""
        return str(value).strip()
    except Exception:
        return ""


def iter_page_annotations(page):
    try:
        annots_obj = page.get("/Annots")
    except Exception:
        annots_obj = None
    if annots_obj is None:
        return []
    annots_array = resolve_pdf_object(annots_obj)
    result = []
    try:
        for ref in annots_array:
            annot = resolve_pdf_object(ref)
            if annot is not None:
                result.append((ref, annot))
    except Exception:
        pass
    return result


def pdf_reference_key(value, resolved=None, fallback_index=None):
    """Stable key for an indirect PDF object/reference when possible."""
    if value is not None:
        try:
            return "{}:{}".format(int(value.idnum), int(value.generation))
        except Exception:
            pass
    obj = resolved if resolved is not None else resolve_pdf_object(value)
    if obj is not None:
        try:
            ref = obj.indirect_reference
            if ref is not None:
                return "{}:{}".format(int(ref.idnum), int(ref.generation))
        except Exception:
            pass
    if fallback_index is not None:
        return "direct:{}".format(int(fallback_index))
    return None


def annotation_group_parent_key(annot):
    """
    PDF annotation grouping uses /IRT to point to the primary/parent annotation
    and /RT /Group to mark the relationship as a group rather than a reply.
    """
    try:
        relation = pdf_name(resolve_pdf_object(annot.get("/RT", "")), "")
    except Exception:
        relation = ""
    if relation != "/Group":
        return None
    try:
        irt = annot.get("/IRT")
    except Exception:
        irt = None
    if irt is None:
        return None
    return pdf_reference_key(irt, resolve_pdf_object(irt), None)


def build_bluebeam_group_info(page):
    """
    Return top-level Bluebeam/PDF annotation groups.

    Nested /IRT + /RT /Group chains are intentionally flattened to the outermost
    root. This maps best to one Revit Detail Group per review item and avoids
    nested Revit group edit/maintenance complexity.
    """
    records = []
    by_key = {}
    parent_map = {}

    for idx, (ref, annot) in enumerate(iter_page_annotations(page)):
        key = pdf_reference_key(ref, annot, idx)
        record = {
            "key": key,
            "ref": ref,
            "annot": annot,
            "index": idx,
            "visual": is_visual_markup_annotation(annot),
            "subject": get_annotation_text(annot, "/Subj"),
        }
        records.append(record)
        by_key[key] = record
        parent_key = annotation_group_parent_key(annot)
        if parent_key:
            parent_map[key] = parent_key

    def root_for(key):
        current = key
        seen = set()
        while current in parent_map:
            if current in seen:
                break
            seen.add(current)
            parent = parent_map.get(current)
            if not parent:
                break
            current = parent
        return current

    related = set(parent_map.keys()) | set(parent_map.values())
    grouped = {}
    for record in records:
        key = record["key"]
        if not record["visual"] or key not in related:
            continue
        root = root_for(key)
        grouped.setdefault(root, []).append(key)

    groups = []
    grouped_keys = set()
    for root_key, member_keys in grouped.items():
        # Keep source page order and unique keys.
        unique_members = []
        seen_members = set()
        for rec in records:
            key = rec["key"]
            if key in member_keys and key not in seen_members:
                seen_members.add(key)
                unique_members.append(key)
        if len(unique_members) < 2:
            continue

        root_record = by_key.get(root_key)
        subject = root_record.get("subject", "") if root_record else ""
        if not subject:
            for key in unique_members:
                candidate = by_key.get(key, {}).get("subject", "")
                if candidate:
                    subject = candidate
                    break

        max_depth = 0
        for key in unique_members:
            depth = 0
            current = key
            seen = set()
            while current in parent_map and current not in seen:
                seen.add(current)
                current = parent_map.get(current)
                depth += 1
            max_depth = max(max_depth, depth)

        first_index = min(by_key.get(k, {}).get("index", 10**9) for k in unique_members)
        groups.append({
            "root_key": root_key,
            "member_keys": unique_members,
            "subject": subject,
            "member_count": len(unique_members),
            "max_depth": max_depth,
            "first_index": first_index,
        })
        grouped_keys.update(unique_members)

    groups.sort(key=lambda item: item.get("first_index", 0))
    nested_relations = 0
    for child_key, parent_key in parent_map.items():
        if parent_key in parent_map:
            nested_relations += 1

    return {
        "groups": groups,
        "group_count": len(groups),
        "grouped_markup_count": len(grouped_keys),
        "nested_relations": nested_relations,
        "grouped_keys": grouped_keys,
        "records": records,
        "by_key": by_key,
    }


def annotation_rgb(annot):
    try:
        c = pdf_number_list(annot.get("/C"))
    except Exception:
        c = []
    if len(c) == 1:
        g = int(round(clamp(c[0], 0.0, 1.0) * 255.0))
        return (g, g, g)
    if len(c) >= 3:
        if len(c) == 4:
            # CMYK -> RGB approximation.
            cyan, magenta, yellow, black = [clamp(v, 0.0, 1.0) for v in c[:4]]
            r = int(round(255.0 * (1.0 - cyan) * (1.0 - black)))
            g = int(round(255.0 * (1.0 - magenta) * (1.0 - black)))
            b = int(round(255.0 * (1.0 - yellow) * (1.0 - black)))
            return (r, g, b)
        return tuple(int(round(clamp(v, 0.0, 1.0) * 255.0)) for v in c[:3])
    return GENERIC_MARKUP_RGB


def annotation_line_width_pdf(annot):
    try:
        bs = resolve_pdf_object(annot.get("/BS"))
        if bs is not None and hasattr(bs, "get"):
            width = pdf_float(bs.get("/W"), 0.0)
            if width > 0:
                return width
    except Exception:
        pass
    try:
        border = pdf_number_list(annot.get("/Border"))
        if len(border) >= 3 and border[2] > 0:
            return float(border[2])
    except Exception:
        pass
    return 1.0


def annotation_rect(annot):
    vals = pdf_number_list(annot.get("/Rect"))
    if len(vals) < 4:
        return None
    x0 = min(vals[0], vals[2])
    y0 = min(vals[1], vals[3])
    x1 = max(vals[0], vals[2])
    y1 = max(vals[1], vals[3])
    return (x0, y0, x1, y1)


def page_geometry(page):
    box = page.cropbox
    left = float(box.left)
    bottom = float(box.bottom)
    right = float(box.right)
    top = float(box.top)
    width = right - left
    height = top - bottom
    if width <= 1.0e-9 or height <= 1.0e-9:
        raise Exception("PDF CropBox không hợp lệ.")
    try:
        rotation = int(page.rotation or 0) % 360
    except Exception:
        rotation = pdf_int(page.get("/Rotate"), 0) % 360
    if rotation not in (0, 90, 180, 270):
        rotation = int(round(rotation / 90.0) * 90) % 360
    display_width = height if rotation in (90, 270) else width
    display_height = width if rotation in (90, 270) else height
    return {
        "left": left,
        "bottom": bottom,
        "right": right,
        "top": top,
        "width": width,
        "height": height,
        "rotation": rotation,
        "display_width": display_width,
        "display_height": display_height,
    }


def analyze_pdf_page(pdf_path, page_number):
    with open(pdf_path, "rb") as stream:
        reader = open_reader_from_stream(stream)
        page_count = len(reader.pages)
        if page_number < 1 or page_number > page_count:
            raise Exception(
                "Trang {} không hợp lệ. PDF có {} trang.".format(page_number, page_count)
            )
        page = reader.pages[page_number - 1]
        rows = []
        type_counts = {}
        author_counts = {}
        total = 0
        visible = 0
        for _ref, annot in iter_page_annotations(page):
            total += 1
            subtype = annot_subtype(annot) or "/Unknown"
            author = get_annotation_text(annot, "/T")
            subject = get_annotation_text(annot, "/Subj")
            content = get_annotation_text(annot, "/Contents")
            visual = is_visual_markup_annotation(annot)
            if visual:
                visible += 1
                clean_type = subtype[1:] if subtype.startswith("/") else subtype
                type_counts[clean_type] = type_counts.get(clean_type, 0) + 1
                if author:
                    author_counts[author] = author_counts.get(author, 0) + 1
            rows.append(
                {
                    "type": subtype,
                    "author": author,
                    "subject": subject,
                    "content": content,
                    "visual": visual,
                }
            )
        group_info = build_bluebeam_group_info(page)
        return {
            "page_count": int(page_count),
            "page_number": int(page_number),
            "total_annotations": int(total),
            "visible_markups": int(visible),
            "type_counts": type_counts,
            "author_counts": author_counts,
            "annotations": rows,
            "bluebeam_group_count": int(group_info["group_count"]),
            "grouped_markup_count": int(group_info["grouped_markup_count"]),
            "nested_group_relations": int(group_info["nested_relations"]),
            "fingerprint": get_pdf_fingerprint(pdf_path),
            "page_geometry": page_geometry(page),
        }


def format_analysis(analysis):
    lines = []
    lines.append("PDF ANALYSIS")
    lines.append("")
    lines.append("Page: {} / {}".format(analysis["page_number"], analysis["page_count"]))
    lines.append("All annotations: {}".format(analysis["total_annotations"]))
    lines.append("Visual markups: {}".format(analysis["visible_markups"]))
    lines.append("Bluebeam groups: {}".format(analysis.get("bluebeam_group_count", 0)))
    lines.append("Grouped markups: {}".format(analysis.get("grouped_markup_count", 0)))
    if analysis.get("nested_group_relations", 0):
        lines.append("Nested group relations: {} (V2.5 flattens to outer parent)".format(analysis.get("nested_group_relations", 0)))
    if analysis["type_counts"]:
        lines.append("")
        lines.append("Types:")
        for key in sorted(analysis["type_counts"].keys()):
            lines.append("  {}: {}".format(key, analysis["type_counts"][key]))
    if analysis["author_counts"]:
        lines.append("")
        lines.append("Authors:")
        for key in sorted(analysis["author_counts"].keys()):
            lines.append("  {}: {}".format(key, analysis["author_counts"][key]))
    lines.append("")
    if analysis["visible_markups"] <= 0:
        lines.append("Không thấy unflattened markup. Nếu PDF vẫn có markup nhìn thấy, có thể nó đã Flatten.")
    else:
        lines.append("V2.5 có thể chuyển markup hình học sang native Revit detail elements và giữ Bluebeam Group dưới dạng Detail Group.")
    return "\n".join(lines)


