# BASE PDF CACHE
# ============================================================


def get_cache_dir():
    root = os.environ.get("LOCALAPPDATA") or os.environ.get("TEMP") or TOOL_DIR
    path = os.path.join(root, "AnTools", CACHE_FOLDER_NAME)
    if not os.path.exists(path):
        os.makedirs(path)
    return path


def make_base_cache_path(pdf_path, page_number, fingerprint):
    base_name = safe_filename(os.path.splitext(os.path.basename(pdf_path))[0])
    stem = "{}__p{:03d}__{}".format(base_name, int(page_number), fingerprint[:12])
    return os.path.join(get_cache_dir(), stem + "__BASE.pdf")


def remove_file_if_exists(path):
    try:
        if path and os.path.exists(path):
            os.remove(path)
    except Exception:
        pass


def write_pdf_writer(writer, output_path):
    remove_file_if_exists(output_path)
    with open(output_path, "wb") as out_stream:
        writer.write(out_stream)
    if not os.path.exists(output_path) or os.path.getsize(output_path) <= 0:
        raise Exception("Không ghi được PDF tạm: {}".format(output_path))


def create_base_pdf(pdf_path, page_number, output_path):
    with open(pdf_path, "rb") as stream:
        reader = open_reader_from_stream(stream)
        idx = int(page_number) - 1
        if idx < 0 or idx >= len(reader.pages):
            raise Exception("PDF page ngoài phạm vi.")
        writer = PdfWriter()
        writer.add_page(reader.pages[idx])
        out_page = writer.pages[0]
        annots_key = NameObject("/Annots")
        if annots_key in out_page:
            del out_page[annots_key]
        write_pdf_writer(writer, output_path)
    return output_path


# ============================================================
# REVIT BASE IMAGE HELPERS
# ============================================================


def get_active_view_center(ui_document, view):
    try:
        for uiview in ui_document.GetOpenUIViews():
            if uiview.ViewId == view.Id:
                corners = uiview.GetZoomCorners()
                p1 = corners[0]
                p2 = corners[1]
                return XYZ(
                    (p1.X + p2.X) / 2.0,
                    (p1.Y + p2.Y) / 2.0,
                    (p1.Z + p2.Z) / 2.0,
                )
    except Exception:
        pass
    try:
        return view.Origin
    except Exception:
        return XYZ(0, 0, 0)


def create_generated_image_options(file_path, page_number=1):
    options = ImageTypeOptions(file_path, False, GENERATED_IMAGE_SOURCE)
    try:
        options.PageNumber = int(page_number)
    except Exception:
        pass
    return options


def create_center_placement_options(center_point):
    try:
        return ImagePlacementOptions(center_point, BoxPlacement.Center)
    except Exception:
        placement = ImagePlacementOptions()
        try:
            placement.Location = center_point
        except Exception:
            pass
        try:
            placement.PlacementPoint = BoxPlacement.Center
        except Exception:
            pass
        return placement


def apply_instance_scale(image_instance, scale_value):
    try:
        image_instance.LockProportions = True
    except Exception:
        pass
    applied = False
    try:
        image_instance.WidthScale = float(scale_value)
        image_instance.HeightScale = float(scale_value)
        applied = True
    except Exception:
        pass
    if not applied:
        for pname in ["Scale", "Width Scale", "Height Scale"]:
            try:
                param = image_instance.LookupParameter(pname)
                if param and not param.IsReadOnly:
                    param.Set(float(scale_value))
                    applied = True
            except Exception:
                pass
    return applied


def image_point(image_instance, placement):
    return image_instance.GetLocation(placement)


def image_frame(image_instance):
    return {
        "center": image_point(image_instance, BoxPlacement.Center),
        "bl": image_point(image_instance, BoxPlacement.BottomLeft),
        "br": image_point(image_instance, BoxPlacement.BottomRight),
        "tl": image_point(image_instance, BoxPlacement.TopLeft),
        "tr": image_point(image_instance, BoxPlacement.TopRight),
        "width": float(image_instance.Width),
        "height": float(image_instance.Height),
    }


def choose_placement_point(placement_mode):
    if placement_mode == PLACEMENT_PICK:
        try:
            return uidoc.Selection.PickPoint("Chọn điểm đặt BASE PDF. Điểm này là tâm PDF.")
        except OperationCanceledException:
            return None
    return get_active_view_center(uidoc, active_view)


def create_image_type_and_instance(file_path, center_point, initial_scale=None):
    options = create_generated_image_options(file_path, 1)
    image_type = ImageType.Create(doc, options)
    placement = create_center_placement_options(center_point)
    instance = ImageInstance.Create(doc, active_view, image_type.Id, placement)
    if initial_scale is not None:
        apply_instance_scale(instance, initial_scale)
    return image_type, instance


# ============================================================
# PDF -> REVIT COORDINATE MAPPING
# ============================================================


def rotate_normalized_uv(u, v, rotation):
    rot = int(rotation or 0) % 360
    if rot == 90:
        return v, 1.0 - u
    if rot == 180:
        return 1.0 - u, 1.0 - v
    if rot == 270:
        return 1.0 - v, u
    return u, v


def pdf_xy_to_revit(x, y, geom, frame):
    u = (float(x) - geom["left"]) / geom["width"]
    v = (float(y) - geom["bottom"]) / geom["height"]
    u, v = rotate_normalized_uv(u, v, geom["rotation"])
    xvec = frame["br"] - frame["bl"]
    yvec = frame["tl"] - frame["bl"]
    return frame["bl"] + xvec.Multiply(u) + yvec.Multiply(v)


def pdf_points_to_revit(points, geom, frame):
    return [pdf_xy_to_revit(x, y, geom, frame) for x, y in points]


def rect_pdf_points(rect):
    if rect is None:
        return []
    x0, y0, x1, y1 = rect
    return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]


def pair_points(values):
    result = []
    for i in range(0, len(values) - 1, 2):
        result.append((float(values[i]), float(values[i + 1])))
    return result


def decimate_points(points, max_points=MAX_POINTS_PER_PATH):
    if len(points) <= max_points:
        return list(points)
    if max_points < 2:
        return [points[0]]
    result = []
    last_index = len(points) - 1
    for i in range(max_points):
        idx = int(round((float(i) / float(max_points - 1)) * last_index))
        p = points[idx]
        if not result or p != result[-1]:
            result.append(p)
    return result


# ============================================================
# REVIT NATIVE STYLE / TEXT HELPERS
# ============================================================


def parse_line_weight(value):
    try:
        return int(clamp(int(str(value)), 1, 16))
    except Exception:
        return int(DEFAULT_LINE_WEIGHT)


def find_line_subcategory(name):
    lines_cat = doc.Settings.Categories.get_Item(BuiltInCategory.OST_Lines)
    try:
        for subcat in lines_cat.SubCategories:
            if str(subcat.Name) == str(name):
                return subcat
    except Exception:
        pass
    return None


def get_or_create_markup_graphics_style(rgb, line_weight, cache):
    key = (int(rgb[0]), int(rgb[1]), int(rgb[2]), int(line_weight))
    if key in cache:
        return cache[key]

    r, g, b, weight = key
    name = "AnTools_Bluebeam_R{:03d}_G{:03d}_B{:03d}_W{:02d}".format(r, g, b, weight)
    lines_cat = doc.Settings.Categories.get_Item(BuiltInCategory.OST_Lines)
    subcat = find_line_subcategory(name)
    if subcat is None:
        subcat = doc.Settings.Categories.NewSubcategory(lines_cat, name)
    try:
        subcat.LineColor = Color(r, g, b)
    except Exception:
        pass
    try:
        subcat.SetLineWeight(weight, GraphicsStyleType.Projection)
    except Exception:
        pass
    style = subcat.GetGraphicsStyle(GraphicsStyleType.Projection)
    if style is None:
        raise Exception("Không tạo được Revit line style '{}'".format(name))
    cache[key] = style
    return style


def default_text_note_type():
    try:
        collector = FilteredElementCollector(doc).OfClass(TextNoteType).WhereElementIsElementType()
        for item in collector:
            return item
    except Exception:
        pass
    return None


def get_or_create_text_type(paper_size_ft, cache):
    # Round to 0.5 mm to avoid creating too many types.
    mm = clamp(float(paper_size_ft) * 304.8, 1.5, 10.0)
    mm = round(mm * 2.0) / 2.0
    key = round(mm, 1)
    if key in cache:
        return cache[key]

    name = "AnTools_Bluebeam_Text_{}mm".format(str(key).replace(".", "p"))
    try:
        collector = FilteredElementCollector(doc).OfClass(TextNoteType).WhereElementIsElementType()
        for item in collector:
            try:
                if str(item.Name) == name:
                    cache[key] = item
                    return item
            except Exception:
                pass
    except Exception:
        pass

    base_type = default_text_note_type()
    if base_type is None:
        return None
    try:
        new_type = base_type.Duplicate(name)
        param = new_type.get_Parameter(BuiltInParameter.TEXT_SIZE)
        if param is not None and not param.IsReadOnly:
            param.Set(mm / 304.8)
        cache[key] = new_type
        return new_type
    except Exception:
        cache[key] = base_type
        return base_type


def parse_free_text_font_size(annot):
    da = get_annotation_text(annot, "/DA")
    if not da:
        try:
            ap = resolve_pdf_object(annot.get("/AP"))
            normal = resolve_pdf_object(ap.get("/N")) if ap is not None else None
            if normal is not None:
                data = normal.get_data()
                if isinstance(data, bytes):
                    da = data.decode("latin-1", "ignore")
                else:
                    da = str(data)
        except Exception:
            da = ""
    if da:
        try:
            match = re.search(r"([0-9]+(?:\.[0-9]+)?)\s+Tf\b", da)
            if match:
                return clamp(float(match.group(1)), 4.0, 72.0)
        except Exception:
            pass
    return 10.0


def text_paper_size_ft(font_size_pdf, geom, frame):
    display_h = max(float(geom.get("display_height", 1.0)), 1.0e-9)
    model_ft_per_pdf = float(frame["height"]) / display_h
    try:
        view_scale = max(float(active_view.Scale), 1.0)
    except Exception:
        view_scale = 1.0
    paper_ft = float(font_size_pdf) * model_ft_per_pdf / view_scale
    # If the PDF/model scale is unusual, fall back to a readable 2.5mm.
    paper_mm = paper_ft * 304.8
    if paper_mm < 0.8 or paper_mm > 20.0:
        return 2.5 / 304.8
    return paper_ft


# ============================================================
# NATIVE DETAIL CREATION HELPERS
# ============================================================


def short_curve_tolerance():
    try:
        return float(doc.Application.ShortCurveTolerance)
    except Exception:
        return 1.0e-5


def create_detail_segment(p1, p2, style, created_ids):
    if p1 is None or p2 is None:
        return False
    if xyz_distance(p1, p2) <= short_curve_tolerance() * 1.05:
        return False
    if len(created_ids) >= MAX_NATIVE_ELEMENTS:
        raise Exception(
            "Vượt giới hạn {} native elements. Tool rollback để tránh làm Revit quá nặng.".format(
                MAX_NATIVE_ELEMENTS
            )
        )
    curve = doc.Create.NewDetailCurve(active_view, Line.CreateBound(p1, p2))
    if curve is None:
        return False
    try:
        curve.LineStyle = style
    except Exception:
        pass
    created_ids.append(get_id_int(curve.Id))
    return True


def create_polyline_pdf(points, geom, frame, style, created_ids, closed=False):
    points = decimate_points(points)
    if len(points) < 2:
        return 0
    revit_points = pdf_points_to_revit(points, geom, frame)
    count = 0
    for i in range(len(revit_points) - 1):
        if create_detail_segment(revit_points[i], revit_points[i + 1], style, created_ids):
            count += 1
    if closed and len(revit_points) > 2:
        if create_detail_segment(revit_points[-1], revit_points[0], style, created_ids):
            count += 1
    return count


def create_rect_pdf(rect, geom, frame, style, created_ids):
    return create_polyline_pdf(rect_pdf_points(rect), geom, frame, style, created_ids, True)


def create_ellipse_pdf(rect, geom, frame, style, created_ids):
    if rect is None:
        return 0
    x0, y0, x1, y1 = rect
    cx = (x0 + x1) * 0.5
    cy = (y0 + y1) * 0.5
    rx = (x1 - x0) * 0.5
    ry = (y1 - y0) * 0.5
    if rx <= 0 or ry <= 0:
        return 0
    points = []
    for i in range(ELLIPSE_SEGMENTS):
        a = (2.0 * math.pi * float(i)) / float(ELLIPSE_SEGMENTS)
        points.append((cx + rx * math.cos(a), cy + ry * math.sin(a)))
    return create_polyline_pdf(points, geom, frame, style, created_ids, True)


def line_ending_styles(annot):
    try:
        le = resolve_pdf_object(annot.get("/LE"))
    except Exception:
        le = None
    if le is None:
        return ("/None", "/None")
    try:
        vals = [str(resolve_pdf_object(x)) for x in le]
        if len(vals) >= 2:
            return (vals[0], vals[1])
        if len(vals) == 1:
            return (vals[0], vals[0])
    except Exception:
        pass
    name = str(le)
    return (name, name)


def create_arrowhead_pdf(tip, toward, ending_style, size_pdf, geom, frame, style, created_ids):
    ending = str(ending_style or "/None")
    if ending in ("/None", "None", ""):
        return 0
    tx, ty = float(tip[0]), float(tip[1])
    ox, oy = float(toward[0]), float(toward[1])
    dx = ox - tx
    dy = oy - ty
    length = math.sqrt(dx * dx + dy * dy)
    if length <= 1.0e-9:
        return 0
    ux = dx / length
    uy = dy / length
    px = -uy
    py = ux
    size = min(float(size_pdf), length * 0.35)
    half = size * 0.48
    a = (tx + ux * size + px * half, ty + uy * size + py * half)
    b = (tx + ux * size - px * half, ty + uy * size - py * half)
    count = 0
    if create_polyline_pdf([tip, a], geom, frame, style, created_ids, False):
        count += 1
    if create_polyline_pdf([tip, b], geom, frame, style, created_ids, False):
        count += 1
    if "Closed" in ending or "Diamond" in ending or "Square" in ending:
        if create_polyline_pdf([a, b], geom, frame, style, created_ids, False):
            count += 1
    return count


def create_line_with_endings_pdf(points, annot, geom, frame, style, created_ids, draw_arrows):
    if len(points) < 2:
        return 0
    count = create_polyline_pdf(points, geom, frame, style, created_ids, False)
    if not draw_arrows:
        return count
    start_style, end_style = line_ending_styles(annot)
    size = clamp(6.0 + annotation_line_width_pdf(annot) * 2.5, 6.0, 24.0)
    count += create_arrowhead_pdf(points[0], points[1], start_style, size, geom, frame, style, created_ids)
    count += create_arrowhead_pdf(points[-1], points[-2], end_style, size, geom, frame, style, created_ids)
    return count


def create_quad_text_markup(annot, subtype, geom, frame, style, created_ids):
    vals = pdf_number_list(annot.get("/QuadPoints"))
    if len(vals) < 8:
        rect = annotation_rect(annot)
        return create_rect_pdf(rect, geom, frame, style, created_ids) if rect else 0
    count = 0
    for i in range(0, len(vals) - 7, 8):
        p0 = (vals[i], vals[i + 1])
        p1 = (vals[i + 2], vals[i + 3])
        p2 = (vals[i + 4], vals[i + 5])
        p3 = (vals[i + 6], vals[i + 7])
        if subtype == "/Highlight":
            count += create_polyline_pdf([p0, p1, p3, p2], geom, frame, style, created_ids, True)
        elif subtype in ("/Underline", "/Squiggly"):
            count += create_polyline_pdf([p2, p3], geom, frame, style, created_ids, False)
        elif subtype == "/StrikeOut":
            a = ((p0[0] + p2[0]) * 0.5, (p0[1] + p2[1]) * 0.5)
            b = ((p1[0] + p3[0]) * 0.5, (p1[1] + p3[1]) * 0.5)
            count += create_polyline_pdf([a, b], geom, frame, style, created_ids, False)
    return count


def create_text_note_from_annotation(annot, geom, frame, created_ids, text_type_cache):
    text = get_annotation_text(annot, "/Contents")
    if not text:
        # Bluebeam normally writes /Contents, but some rich FreeText keeps useful
        # text in /RC. Strip simple XML/HTML tags as a conservative fallback.
        rich = get_annotation_text(annot, "/RC")
        if rich:
            try:
                text = re.sub(r"<[^>]+>", " ", rich)
                text = re.sub(r"\s+", " ", text).strip()
            except Exception:
                text = rich
    if not text:
        return 0
    rect = annotation_rect(annot)
    if rect is None:
        return 0
    x0, y0, x1, y1 = rect
    position = pdf_xy_to_revit(x0, y1, geom, frame)
    font_size = parse_free_text_font_size(annot)
    paper_size = text_paper_size_ft(font_size, geom, frame)
    text_type = get_or_create_text_type(paper_size, text_type_cache)
    if text_type is None:
        return 0
    if len(created_ids) >= MAX_NATIVE_ELEMENTS:
        raise Exception("Vượt giới hạn native elements.")
    note = TextNote.Create(doc, active_view.Id, position, text, text_type.Id)
    created_ids.append(get_id_int(note.Id))

    # Align text baseline to PDF local X direction after page/base rotations.
    try:
        p0 = pdf_xy_to_revit(x0, y0, geom, frame)
        p1 = pdf_xy_to_revit(x0 + 1.0, y0, geom, frame)
        target = normalized(p1 - p0)
        view_right = normalized(active_view.RightDirection)
        normal = normalized(active_view.ViewDirection)
        if target is not None and view_right is not None and normal is not None:
            dot = clamp(view_right.DotProduct(target), -1.0, 1.0)
            angle = math.atan2(normal.DotProduct(view_right.CrossProduct(target)), dot)
            annot_rotate = pdf_int(annot.get("/Rotate"), 0)
            if annot_rotate:
                angle -= math.radians(float(annot_rotate))
            if abs(angle) > 1.0e-8:
                axis = Line.CreateBound(position, position + normal)
                ElementTransformUtils.RotateElement(doc, note.Id, axis, angle)
    except Exception:
        pass
    return 1


def create_free_text_callout(annot, geom, frame, style, created_ids):
    vals = pdf_number_list(annot.get("/CL"))
    points = pair_points(vals)
    if len(points) < 2:
        return 0
    return create_polyline_pdf(points, geom, frame, style, created_ids, False)


def convert_one_annotation(annot, geom, frame, style, options, created_ids, text_type_cache):
    subtype = annot_subtype(annot)
    draw_arrows = bool(options.get("draw_arrows", True))
    create_text = bool(options.get("create_text", True))
    convert_text_marks = bool(options.get("convert_text_marks", False))
    before = len(created_ids)

    if subtype == "/Line":
        points = pair_points(pdf_number_list(annot.get("/L")))
        if len(points) >= 2:
            create_line_with_endings_pdf(points[:2], annot, geom, frame, style, created_ids, draw_arrows)

    elif subtype in ("/PolyLine", "/Polygon"):
        points = pair_points(pdf_number_list(annot.get("/Vertices")))
        if points:
            if subtype == "/PolyLine":
                create_line_with_endings_pdf(points, annot, geom, frame, style, created_ids, draw_arrows)
            else:
                create_polyline_pdf(points, geom, frame, style, created_ids, True)

    elif subtype in ("/Square", "/Redact", "/Cloud"):
        create_rect_pdf(annotation_rect(annot), geom, frame, style, created_ids)

    elif subtype in ("/Circle", "/Arc"):
        create_ellipse_pdf(annotation_rect(annot), geom, frame, style, created_ids)

    elif subtype == "/Ink":
        ink_list = resolve_pdf_object(annot.get("/InkList"))
        try:
            for path in ink_list:
                points = pair_points(pdf_number_list(path))
                create_polyline_pdf(points, geom, frame, style, created_ids, False)
        except Exception:
            pass

    elif subtype == "/FreeText":
        create_free_text_callout(annot, geom, frame, style, created_ids)
        if create_text:
            create_text_note_from_annotation(annot, geom, frame, created_ids, text_type_cache)
        elif annotation_rect(annot) is not None:
            create_rect_pdf(annotation_rect(annot), geom, frame, style, created_ids)

    elif subtype == "/Text":
        if create_text:
            create_text_note_from_annotation(annot, geom, frame, created_ids, text_type_cache)
        else:
            create_rect_pdf(annotation_rect(annot), geom, frame, style, created_ids)

    elif subtype in ("/Highlight", "/Underline", "/StrikeOut", "/Squiggly"):
        if convert_text_marks:
            create_quad_text_markup(annot, subtype, geom, frame, style, created_ids)

    elif subtype == "/Stamp":
        # Stamp appearance can contain raster/vector/form XObjects. V2.5 deliberately
        # does not rasterize it because the goal is native Revit geometry only.
        pass

    else:
        # Conservative geometry fallback for uncommon Bluebeam/custom subtypes.
        vertices = pair_points(pdf_number_list(annot.get("/Vertices")))
        line_points = pair_points(pdf_number_list(annot.get("/L")))
        if vertices:
            create_polyline_pdf(vertices, geom, frame, style, created_ids, False)
        elif len(line_points) >= 2:
            create_line_with_endings_pdf(line_points[:2], annot, geom, frame, style, created_ids, draw_arrows)
        elif subtype not in ("/Stamp",) and annotation_rect(annot) is not None:
            create_rect_pdf(annotation_rect(annot), geom, frame, style, created_ids)

    return len(created_ids) - before


def sanitize_revit_group_label(text):
    value = str(text or "").strip()
    value = re.sub(r"[\\/:{}\[\]|;<>?`~]", "_", value)
    value = re.sub(r"\s+", " ", value).strip()
    if not value:
        value = "Group"
    return value[:60]


def existing_group_type_names():
    names = set()
    try:
        for gt in FilteredElementCollector(doc).OfClass(GroupType):
            try:
                names.add(str(gt.Name))
            except Exception:
                pass
    except Exception:
        pass
    return names


def unique_group_type_name(base_name, used_names):
    candidate = str(base_name)
    if candidate not in used_names:
        used_names.add(candidate)
        return candidate
    index = 2
    while True:
        candidate = "{}_{}".format(base_name, index)
        if candidate not in used_names:
            used_names.add(candidate)
            return candidate
        index += 1


def desired_group_name(group_record, sequence_index, naming_mode, used_names):
    subject = sanitize_revit_group_label(group_record.get("subject", ""))
    if naming_mode == GROUP_NAMING_SUBJECT and group_record.get("subject", "").strip():
        base = "AnTools_BB_{}_{}".format(subject, str(sequence_index).zfill(3))
    else:
        base = "AnTools_BB_Group_{}".format(str(sequence_index).zfill(3))
    return unique_group_type_name(base, used_names)


def create_revit_detail_groups(group_info, annotation_created_ids, options):
    preserve_groups = bool(options.get("preserve_groups", DEFAULT_PRESERVE_GROUPS))
    naming_mode = str(options.get("group_naming", DEFAULT_GROUP_NAMING))
    if naming_mode not in (GROUP_NAMING_SUBJECT, GROUP_NAMING_SEQUENCE):
        naming_mode = DEFAULT_GROUP_NAMING

    result = {
        "group_ids": [],
        "group_type_ids": [],
        "grouped_member_ids": set(),
        "groups_detected": int(group_info.get("group_count", 0)),
        "grouped_markups_detected": int(group_info.get("grouped_markup_count", 0)),
        "nested_relations": int(group_info.get("nested_relations", 0)),
        "groups_created": 0,
        "groups_skipped": 0,
        "groups_failed": 0,
        "grouped_markups_created": 0,
        "grouped_native_elements": 0,
        "group_names": [],
        "group_errors": [],
    }
    if not preserve_groups or not group_info.get("groups"):
        return result

    # Autodesk recommends regenerate before grouping newly created elements.
    doc.Regenerate()
    used_names = existing_group_type_names()

    for sequence_index, group_record in enumerate(group_info.get("groups", []), 1):
        member_ids = []
        converted_markup_keys = []
        seen_ids = set()

        for key in group_record.get("member_keys", []):
            ids_for_markup = annotation_created_ids.get(key, []) or []
            if ids_for_markup:
                converted_markup_keys.append(key)
            for raw_id in ids_for_markup:
                ivalue = int(raw_id)
                if ivalue not in seen_ids and get_element_by_saved_id(doc, ivalue) is not None:
                    seen_ids.add(ivalue)
                    member_ids.append(ivalue)

        # A Bluebeam group only becomes a Revit group when at least two source
        # markups survived conversion. This avoids grouping several segments that
        # all came from one markup while the other group members were unsupported.
        if len(converted_markup_keys) < 2 or len(member_ids) < 2:
            result["groups_skipped"] += 1
            continue

        ids = List[ElementId]()
        for value in member_ids:
            eid = to_element_id(value)
            if eid is not None:
                ids.Add(eid)
        if ids.Count < 2:
            result["groups_skipped"] += 1
            continue

        sub = SubTransaction(doc)
        sub.Start()
        try:
            revit_group = doc.Create.NewGroup(ids)
            doc.Regenerate()

            group_name = desired_group_name(
                group_record, sequence_index, naming_mode, used_names
            )
            try:
                revit_group.GroupType.Name = group_name
            except Exception:
                # Group itself is still valid even if a project naming rule blocks rename.
                try:
                    group_name = str(revit_group.GroupType.Name)
                except Exception:
                    group_name = "Group"

            group_id = get_id_int(revit_group.Id)
            group_type_id = get_id_int(revit_group.GroupType.Id)
            sub.Commit()

            result["group_ids"].append(group_id)
            result["group_type_ids"].append(group_type_id)
            result["group_names"].append(group_name)
            result["groups_created"] += 1
            result["grouped_markups_created"] += len(converted_markup_keys)
            result["grouped_native_elements"] += len(member_ids)
            for value in member_ids:
                result["grouped_member_ids"].add(int(value))
        except Exception as ex:
            try:
                sub.RollBack()
            except Exception:
                pass
            result["groups_failed"] += 1
            if len(result["group_errors"]) < 10:
                result["group_errors"].append(str(ex))

    return result


def convert_pdf_markups_to_native(pdf_path, page_number, base_instance, options):
    frame = image_frame(base_instance)
    line_weight = parse_line_weight(options.get("line_weight", DEFAULT_LINE_WEIGHT))
    preserve_colors = bool(options.get("preserve_colors", True))
    created_ids = []
    style_cache = {}
    text_type_cache = {}
    annotation_created_ids = {}
    stats = {
        "visual_markups": 0,
        "converted_markups": 0,
        "unsupported_markups": 0,
        "created_elements": 0,
        "output_elements": 0,
        "type_created": {},
        "type_unsupported": {},
        "bluebeam_groups_detected": 0,
        "grouped_markups_detected": 0,
        "nested_group_relations": 0,
        "revit_groups_created": 0,
        "groups_skipped": 0,
        "groups_failed": 0,
        "grouped_markups_created": 0,
        "grouped_native_elements": 0,
        "group_names": [],
        "group_errors": [],
    }

    with open(pdf_path, "rb") as stream:
        reader = open_reader_from_stream(stream)
        idx = int(page_number) - 1
        if idx < 0 or idx >= len(reader.pages):
            raise Exception("PDF page ngoài phạm vi.")
        page = reader.pages[idx]
        geom = page_geometry(page)
        group_info = build_bluebeam_group_info(page)
        stats["bluebeam_groups_detected"] = int(group_info.get("group_count", 0))
        stats["grouped_markups_detected"] = int(group_info.get("grouped_markup_count", 0))
        stats["nested_group_relations"] = int(group_info.get("nested_relations", 0))

        for annot_index, (ref, annot) in enumerate(iter_page_annotations(page)):
            if not is_visual_markup_annotation(annot):
                continue
            stats["visual_markups"] += 1
            subtype = annot_subtype(annot) or "/Unknown"
            clean = subtype[1:] if subtype.startswith("/") else subtype
            rgb = annotation_rgb(annot) if preserve_colors else GENERIC_MARKUP_RGB
            style = get_or_create_markup_graphics_style(rgb, line_weight, style_cache)
            annot_key = pdf_reference_key(ref, annot, annot_index)

            before = len(created_ids)
            try:
                created = convert_one_annotation(
                    annot, geom, frame, style, options, created_ids, text_type_cache
                )
            except Exception as annotation_ex:
                if "Vượt giới hạn" in str(annotation_ex):
                    raise
                created = len(created_ids) - before

            ids_for_annot = [int(v) for v in created_ids[before:]]
            annotation_created_ids[annot_key] = ids_for_annot

            if created > 0:
                stats["converted_markups"] += 1
                stats["type_created"][clean] = stats["type_created"].get(clean, 0) + 1
            else:
                stats["unsupported_markups"] += 1
                stats["type_unsupported"][clean] = stats["type_unsupported"].get(clean, 0) + 1

        group_result = create_revit_detail_groups(
            group_info, annotation_created_ids, options
        )

    grouped_member_ids = group_result.get("grouped_member_ids", set())
    ungrouped_ids = [int(v) for v in created_ids if int(v) not in grouped_member_ids]
    group_ids = [int(v) for v in group_result.get("group_ids", [])]
    group_type_ids = [int(v) for v in group_result.get("group_type_ids", [])]

    stats["created_elements"] = len(created_ids)
    stats["output_elements"] = len(ungrouped_ids) + len(group_ids)
    stats["revit_groups_created"] = int(group_result.get("groups_created", 0))
    stats["groups_skipped"] = int(group_result.get("groups_skipped", 0))
    stats["groups_failed"] = int(group_result.get("groups_failed", 0))
    stats["grouped_markups_created"] = int(group_result.get("grouped_markups_created", 0))
    stats["grouped_native_elements"] = int(group_result.get("grouped_native_elements", 0))
    stats["group_names"] = list(group_result.get("group_names", []))
    stats["group_errors"] = list(group_result.get("group_errors", []))

    return ungrouped_ids, group_ids, group_type_ids, stats


# ============================================================
# VISIBILITY / STATE
# ============================================================


def element_id_list_from_values(values):
    ids = List[ElementId]()
    for value in values or []:
        eid = to_element_id(value)
        if eid is not None:
            ids.Add(eid)
    return ids


def valid_elements_from_values(values):
    result = []
    for value in values or []:
        elem = get_element_by_saved_id(doc, value)
        if elem is not None:
            result.append(elem)
    return result


def native_markup_elements(state):
    """Top-level Revit markup outputs used for visibility/status.

    V2.5 stores grouped markup as Group instances and only stores individual
    DetailCurve/TextNote IDs for ungrouped markup. V2.4 state remains compatible.
    """
    if not state:
        return []
    result = []
    seen = set()
    for key in ("markup_group_ids", "markup_element_ids"):
        for elem in valid_elements_from_values(state.get(key, [])):
            eid = get_id_int(elem.Id)
            if eid not in seen:
                seen.add(eid)
                result.append(elem)
    return result


def group_type_is_in_use(group_type_id):
    target = int(group_type_id)
    try:
        for group in FilteredElementCollector(doc).OfClass(Group):
            try:
                if get_id_int(group.GroupType.Id) == target:
                    return True
            except Exception:
                pass
    except Exception:
        pass
    return False


def cleanup_orphan_group_types(group_type_ids):
    for value in group_type_ids or []:
        try:
            ivalue = int(value)
        except Exception:
            continue
        elem = get_element_by_saved_id(doc, ivalue)
        if elem is None:
            continue
        if group_type_is_in_use(ivalue):
            # User may have copied the group. Never delete a type still in use.
            continue
        try:
            doc.Delete(elem.Id)
        except Exception:
            pass


def delete_native_markup_state(state):
    if not state:
        return
    # Group instances must be removed before attempting to clean their types.
    delete_element_values(state.get("markup_group_ids", []))
    try:
        doc.Regenerate()
    except Exception:
        pass
    # In V2.5 these are only ungrouped outputs. In V2.4 migration they are all
    # native elements, which remains safe because markup_group_ids is absent.
    delete_element_values(state.get("markup_element_ids", []))
    try:
        doc.Regenerate()
    except Exception:
        pass
    cleanup_orphan_group_types(state.get("markup_group_type_ids", []))


def legacy_markup_element(state):
    if not state:
        return None
    elem = get_element_by_saved_id(doc, state.get("markup_instance_id"))
    try:
        if elem is not None and elem.OwnerViewId != active_view.Id:
            return None
    except Exception:
        return None
    return elem


def resolve_base_element(state):
    if not state:
        return None
    base = get_element_by_saved_id(doc, state.get("base_instance_id"))
    try:
        if base is not None and base.OwnerViewId != active_view.Id:
            return None
    except Exception:
        return None
    return base


def state_is_stale(state):
    if not state:
        return False
    base = resolve_base_element(state)
    native = native_markup_elements(state)
    legacy = legacy_markup_element(state)
    return base is None and not native and legacy is None


def set_elements_hidden(document, view, elements, hidden):
    if not elements:
        return
    ids = List[ElementId]()
    for elem in elements:
        try:
            can_hide = elem.CanBeHidden(view)
        except Exception:
            can_hide = True
        if not can_hide:
            continue
        try:
            is_hidden = elem.IsHidden(view)
        except Exception:
            is_hidden = False
        if hidden and not is_hidden:
            ids.Add(elem.Id)
        elif (not hidden) and is_hidden:
            ids.Add(elem.Id)
    if ids.Count == 0:
        return
    if hidden:
        view.HideElements(ids)
    else:
        view.UnhideElements(ids)


def visibility_action(which, hidden):
    state = current_state()
    if not state:
        raise Exception("View này chưa có PDF Review.")
    if which == "base":
        elem = resolve_base_element(state)
        if elem is None:
            raise Exception("Không tìm thấy BASE element.")
        elements = [elem]
    else:
        elements = native_markup_elements(state)
        legacy = legacy_markup_element(state)
        if not elements and legacy is not None:
            elements = [legacy]
        if not elements:
            raise Exception("Không tìm thấy Revit markup elements.")
    t = Transaction(doc, "Bluebeam Review Visibility")
    t.Start()
    try:
        set_elements_hidden(doc, active_view, elements, hidden)
        t.Commit()
    except Exception:
        try:
            t.RollBack()
        except Exception:
            pass
        raise


def delete_element_value(value):
    eid = to_element_id(value)
    if eid is None:
        return
    try:
        if doc.GetElement(eid) is not None:
            doc.Delete(eid)
    except Exception:
        pass


def delete_element_values(values):
    for value in values or []:
        delete_element_value(value)


def build_status_text(state, base, native, legacy):
    lines = []
    lines.append("Active View: {}".format(active_view.Name))
    lines.append(
        "pypdf bundled: {} | V2.5 Native Markup + Groups | no pip install".format(
            getattr(pypdf, "__version__", "?")
        )
    )
    if not state:
        lines.append("")
        lines.append("Status: Chưa có review trong view này.")
        lines.append("Chọn 1 PDF Bluebeam rồi bấm Load BASE để dóng.")
        return "\n".join(lines)

    lines.append("")
    lines.append("Source: {}".format(state.get("pdf_path", "")))
    lines.append("Page: {}".format(state.get("page", "?")))
    lines.append("Markup detected: {}".format(state.get("markup_count", "?")))
    lines.append("Bluebeam groups detected: {}".format(state.get("bluebeam_group_count", 0)))

    if base is not None:
        try:
            hidden = base.IsHidden(active_view)
        except Exception:
            hidden = False
        lines.append("BASE: ID {} | {}".format(get_id_int(base.Id), "HIDDEN" if hidden else "VISIBLE"))
    else:
        lines.append("BASE: MISSING")

    if native:
        hidden_count = 0
        for elem in native:
            try:
                if elem.IsHidden(active_view):
                    hidden_count += 1
            except Exception:
                pass
        group_count = len(valid_elements_from_values(state.get("markup_group_ids", [])))
        ungrouped_count = len(valid_elements_from_values(state.get("markup_element_ids", [])))
        lines.append(
            "REVIT MARKUP OUTPUT: {} top-level | {} hidden".format(len(native), hidden_count)
        )
        if group_count:
            lines.append("  Detail Groups: {} | Ungrouped elements: {}".format(group_count, ungrouped_count))
    elif legacy is not None:
        lines.append(
            "LEGACY MARKUP PDF: ID {} | V2.5 Finish sẽ thay bằng native elements/groups".format(
                get_id_int(legacy.Id)
            )
        )
    else:
        lines.append("REVIT MARKUP: chưa tạo")

    if base is not None and not native:
        lines.append("")
        lines.append("Bước tiếp theo: dóng BASE rồi bấm Finish + Create Revit Markup.")
    elif native:
        lines.append("")
        lines.append("Review hoàn tất: markup hiện là native Revit DetailCurve/TextNote/Detail Group.")
    return "\n".join(lines)


