# REVIEW WORKFLOW
# ============================================================


def start_base_review(pdf_path, page_number, scale_value, placement_mode):
    global last_pdf_path, last_scale, last_page, last_placement_mode

    state = current_state()
    if state and not state_is_stale(state):
        raise Exception(
            "View này đã có PDF Review đang tồn tại.\n\n"
            "Hãy Finish/Rebuild hoặc Reset Current Review trước khi Load BASE mới."
        )

    analysis = analyze_pdf_page(pdf_path, page_number)
    if analysis["visible_markups"] <= 0:
        raise Exception(
            "Không tìm thấy Bluebeam markup annotation chưa flatten trên trang {}.\n\n"
            "Nếu PDF vẫn nhìn thấy markup, có khả năng markup đã được Flatten vào page content.".format(
                page_number
            )
        )

    fingerprint = analysis["fingerprint"]
    base_path = make_base_cache_path(pdf_path, page_number, fingerprint)
    create_base_pdf(pdf_path, page_number, base_path)

    placement_point = choose_placement_point(placement_mode)
    if placement_point is None:
        return False

    t = Transaction(doc, "Bluebeam Review V2.5 - Load BASE")
    t.Start()
    try:
        base_type, base_instance = create_image_type_and_instance(
            base_path, placement_point, scale_value
        )
        doc.Regenerate()
        t.Commit()
    except Exception:
        try:
            t.RollBack()
        except Exception:
            pass
        raise

    state = {
        "version": TOOL_VERSION,
        "doc_title": doc.Title,
        "view_id": get_id_int(active_view.Id),
        "view_name": active_view.Name,
        "pdf_path": pdf_path,
        "page": int(page_number),
        "source_fingerprint": fingerprint,
        "scale": float(scale_value),
        "placement_mode": placement_mode,
        "markup_count": int(analysis["visible_markups"]),
        "base_cache": base_path,
        "base_type_id": get_id_int(base_type.Id),
        "base_instance_id": get_id_int(base_instance.Id),
        "markup_element_ids": [],
        "markup_group_ids": [],
        "markup_group_type_ids": [],
        "bluebeam_group_count": int(analysis.get("bluebeam_group_count", 0)),
        "markup_instance_id": None,
        "markup_type_id": None,
        "alignment_completed": False,
    }
    save_review_state(state)

    last_pdf_path = pdf_path
    last_scale = str(scale_value)
    last_page = int(page_number)
    last_placement_mode = placement_mode
    save_global_config()

    alert(
        "Đã tạo BASE không markup và đưa vào Active View.\n\n"
        "BASE ElementId: {}\n"
        "Bluebeam markups detected: {}\nBluebeam groups detected: {}\n\n"
        "Hãy Move / Rotate / Scale BASE để dóng với model/link Revit.\n"
        "Sau đó chạy tool lại và bấm Finish + Create Revit Markup.".format(
            get_id_int(base_instance.Id), analysis["visible_markups"], analysis.get("bluebeam_group_count", 0)
        )
    )
    return True


def finish_alignment(native_options=None, rebuild=False):
    state = current_state()
    if not state:
        raise Exception("View này chưa có BASE để Finish Alignment.")

    base = resolve_base_element(state)
    if base is None:
        raise Exception(
            "Không tìm thấy BASE instance đã lưu. Có thể element đã bị Delete/Undo.\n"
            "Hãy Reset Current Review rồi Load BASE lại."
        )

    existing_native = native_markup_elements(state)
    if existing_native and not rebuild:
        raise Exception("Native Revit markup đã được tạo. Dùng Rebuild nếu muốn tạo lại.")

    source_pdf = state.get("pdf_path")
    page_number = int(state.get("page", 1))
    if not source_pdf or not os.path.exists(source_pdf):
        raise Exception("Không tìm thấy source PDF:\n{}".format(source_pdf))

    current_fingerprint = get_pdf_fingerprint(source_pdf)
    if current_fingerprint != state.get("source_fingerprint"):
        raise Exception(
            "Source PDF đã thay đổi sau khi BASE được tạo.\n\n"
            "Không thể đảm bảo markup còn khớp với BASE đã dóng.\n"
            "Hãy Reset Current Review và Load BASE lại từ PDF hiện tại."
        )

    analysis = analyze_pdf_page(source_pdf, page_number)
    if analysis["visible_markups"] <= 0:
        raise Exception("Source PDF không còn visual markup annotation chưa flatten.")

    options = native_options or {
        "line_weight": DEFAULT_LINE_WEIGHT,
        "preserve_colors": DEFAULT_PRESERVE_COLORS,
        "create_text": DEFAULT_CREATE_TEXT,
        "draw_arrows": DEFAULT_DRAW_ARROWS,
        "convert_text_marks": DEFAULT_CONVERT_TEXT_MARKS,
        "preserve_groups": DEFAULT_PRESERVE_GROUPS,
        "group_naming": DEFAULT_GROUP_NAMING,
    }

    legacy = legacy_markup_element(state)
    t = Transaction(doc, "Bluebeam Review V2.5 - Create Native Markup + Groups")
    t.Start()
    try:
        # Rebuild removes previous native output while preserving the aligned BASE.
        delete_native_markup_state(state)

        # Migrate a V2.3 white-background MARKUP PDF automatically.
        if legacy is not None:
            delete_element_value(state.get("markup_instance_id"))
            delete_element_value(state.get("markup_type_id"))

        ungrouped_ids, group_ids, group_type_ids, stats = convert_pdf_markups_to_native(
            source_pdf, page_number, base, options
        )
        if not ungrouped_ids and not group_ids:
            raise Exception(
                "Không tạo được native Revit markup nào.\n\n"
                "Các markup trên trang có thể chủ yếu là Stamp/image hoặc subtype chưa hỗ trợ."
            )

        set_elements_hidden(doc, active_view, [base], True)
        doc.Regenerate()
        t.Commit()
    except Exception:
        try:
            t.RollBack()
        except Exception:
            pass
        raise

    state["version"] = TOOL_VERSION
    state["markup_element_ids"] = [int(v) for v in ungrouped_ids]
    state["markup_group_ids"] = [int(v) for v in group_ids]
    state["markup_group_type_ids"] = [int(v) for v in group_type_ids]
    state["markup_instance_id"] = None
    state["markup_type_id"] = None
    state["alignment_completed"] = True
    state["markup_count"] = int(analysis["visible_markups"])
    state["bluebeam_group_count"] = int(analysis.get("bluebeam_group_count", 0))
    state["native_line_weight"] = str(options.get("line_weight", DEFAULT_LINE_WEIGHT))
    state["native_preserve_colors"] = bool(options.get("preserve_colors", True))
    state["native_create_text"] = bool(options.get("create_text", True))
    state["native_draw_arrows"] = bool(options.get("draw_arrows", True))
    state["native_convert_text_marks"] = bool(options.get("convert_text_marks", False))
    state["native_preserve_groups"] = bool(options.get("preserve_groups", True))
    state["native_group_naming"] = str(options.get("group_naming", DEFAULT_GROUP_NAMING))
    state["converted_markups"] = int(stats["converted_markups"])
    state["unsupported_markups"] = int(stats["unsupported_markups"])
    state["created_elements"] = int(stats["created_elements"])
    state["revit_groups_created"] = int(stats.get("revit_groups_created", 0))
    state["grouped_markups_created"] = int(stats.get("grouped_markups_created", 0))
    save_review_state(state)

    msg = []
    msg.append("V2.5 Native Revit Markup + Bluebeam Groups hoàn tất.")
    msg.append("")
    msg.append("BASE: hidden")
    msg.append("Native member elements created: {}".format(stats["created_elements"]))
    msg.append("Top-level Revit outputs: {}".format(stats.get("output_elements", 0)))
    msg.append("Converted markups: {} / {}".format(stats["converted_markups"], stats["visual_markups"]))
    msg.append("Unsupported / no geometry: {}".format(stats["unsupported_markups"]))
    msg.append("Line weight: {}".format(parse_line_weight(options.get("line_weight"))))
    msg.append("Preserve colors: {}".format("Yes" if options.get("preserve_colors") else "No - Red"))
    msg.append("")
    msg.append("BLUEBEAM GROUPS")
    msg.append("Detected: {}".format(stats.get("bluebeam_groups_detected", 0)))
    msg.append("Grouped markups detected: {}".format(stats.get("grouped_markups_detected", 0)))
    if stats.get("nested_group_relations", 0):
        msg.append("Nested relations: {} → flattened to outer parent".format(stats.get("nested_group_relations", 0)))
    msg.append("Revit Detail Groups created: {}".format(stats.get("revit_groups_created", 0)))
    msg.append("Markups placed inside Revit groups: {}".format(stats.get("grouped_markups_created", 0)))
    msg.append("Group skipped: {} | failed: {}".format(stats.get("groups_skipped", 0), stats.get("groups_failed", 0)))
    if stats.get("group_names"):
        msg.append("")
        msg.append("Created group types:")
        for name in stats.get("group_names", [])[:12]:
            msg.append("  {}".format(name))
        if len(stats.get("group_names", [])) > 12:
            msg.append("  ... +{} more".format(len(stats.get("group_names", [])) - 12))
    if stats.get("group_errors"):
        msg.append("")
        msg.append("Group errors (first {}):".format(len(stats.get("group_errors", []))))
        for error in stats.get("group_errors", []):
            msg.append("  {}".format(error))
    if stats["type_created"]:
        msg.append("")
        msg.append("Converted by type:")
        for key in sorted(stats["type_created"].keys()):
            msg.append("  {}: {}".format(key, stats["type_created"][key]))
    if stats["type_unsupported"]:
        msg.append("")
        msg.append("Unsupported / skipped by type:")
        for key in sorted(stats["type_unsupported"].keys()):
            msg.append("  {}: {}".format(key, stats["type_unsupported"][key]))
    msg.append("")
    msg.append("Grouped Bluebeam review items giờ có thể select/move/hide như một Revit Detail Group.")
    alert("\n".join(msg))


def reset_current_review():
    state = current_state()
    if not state:
        alert("View này chưa có review để reset.")
        return
    if not ask_yes_no(
        "Reset review hiện tại?\n\n"
        "Tool sẽ xóa BASE, native Revit markup/Detail Groups và legacy MARKUP PDF do tool tạo trong Active View.\n"
        "Các Line Style/Text Type AnTools đã tạo sẽ được giữ lại để tái sử dụng.\n"
        "Group Type chỉ bị xóa nếu không còn Group instance nào khác đang sử dụng."
    ):
        return

    t = Transaction(doc, "Bluebeam Review V2.5 - Reset")
    t.Start()
    try:
        delete_native_markup_state(state)
        delete_element_value(state.get("markup_instance_id"))
        delete_element_value(state.get("base_instance_id"))
        delete_element_value(state.get("markup_type_id"))
        delete_element_value(state.get("base_type_id"))
        t.Commit()
    except Exception:
        try:
            t.RollBack()
        except Exception:
            pass
        raise

    remove_review_state()
    alert("Đã reset PDF Review trong Active View.")


